/*
 * Read the plan's steps as they are NOW, take the step out, put it back at `index` among
 * the others, and write 1..n. Renumbering from the stored order on every move is what makes
 * two quick moves safe: each starts from what the last one left.
 *
 * TWO PASSES: Step has a unique index on (plan, position), checked on every single write,
 * so moving step 3 to place 1 cannot write 1 while another step still holds it. The steps
 * that change are first parked at 100000 + their new place (free, and in the new order
 * among themselves), then written to their new place.
 * TWO MOVES AT ONCE can still meet on a position; the loser's write is refused by that
 * index, so it reads the order again and tries again (up to four times).
 * A shared step that moved rings the learner's doorbell: their timeline order changed.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  const R = Noodl.Records;
  const id = String(Inputs.stepId || '');
  const attempt = async () => {
    const found = id ? await R.query('Step', { objectId: { equalTo: id } }, { limit: 2, plain: true }) : [];
    if (found.length !== 1) return null;
    const moving = found[0];
    const steps = (await R.query('Step', { plan: { equalTo: moving.plan } }, { limit: 1000, plain: true }))
      .sort((a, b) => (a.position - b.position) || String(a.objectId).localeCompare(String(b.objectId)));
    const others = steps.filter((s) => s.objectId !== id);
    const index = Math.max(0, Math.min(Math.round(Number(Inputs.index)) || 0, others.length));
    others.splice(index, 0, moving);
    const changing = others.map((s, i) => ({ s, to: i + 1 })).filter((x) => x.s.position !== x.to);
    for (const x of changing) await R.save(x.s.objectId, { plan: x.s.plan, position: 100000 + x.to }, { className: 'Step' });
    for (const x of changing) await R.save(x.s.objectId, { plan: x.s.plan, position: x.to }, { className: 'Step' });
    if (changing.length && others.some((s) => s.shared === true)) {
      await R.create('Doorbell', { learner: moving.learner, topic: 'plan' }, { acl: { [moving.learner]: { read: true }, 'role:staff': { read: true } } });
    }
    return others.map((s) => s.objectId);
  };
  let lastError = null;
  for (let tries = 0; tries < 4; tries++) {
    try {
      const order = await attempt();
      if (!order) return refuse('That step is no longer in the plan. Reload the page.');
      Outputs.order = order;
      Outputs.done();
      return;
    } catch (e) {
      lastError = e;
      await new Promise((r) => setTimeout(r, 30 + Math.floor(Math.random() * 120)));
    }
  }
  console.error('[dbu:moveStep]', String((lastError && lastError.message) || lastError));
  Outputs.failed();
})();
